<?php
declare(strict_types=1);
require_once __DIR__ . '/../app/bootstrap.php';
use BAJAMA\Core\Auth; use BAJAMA\Core\License; use BAJAMA\Core\RBAC; use BAJAMA\Core\Tenant; use BAJAMA\Network\RouterOSProvisioningService;
Auth::requireLogin(); $db=db(); License::requireFeature($db,'mikrotik'); RBAC::require($db,'network.view');
$organizationId=Tenant::id(); $canManage=RBAC::hasPermission($db,'network.manage'); $message=''; $error='';
if($_SERVER['REQUEST_METHOD']==='POST') { try { verify_csrf((string)($_POST['_csrf']??$_POST['csrf']??'')); if(!$canManage) throw new RuntimeException('Akses ditolak.'); $action=(string)($_POST['action']??''); $id=(int)($_POST['id']??0);
 if($action==='delete'||$action==='toggle'){ $current=$db->prepare('SELECT enabled FROM network_static_ips WHERE id=? AND organization_id=? LIMIT 1'); $current->execute([$id,$organizationId]); $currentEnabled=(int)$current->fetchColumn(); if($action==='delete'){(new RouterOSProvisioningService($db,(int)$organizationId))->remove('network_static_ip',$id);} $sql=$action==='delete'?'DELETE FROM network_static_ips WHERE id=? AND organization_id=?':'UPDATE network_static_ips SET enabled=CASE WHEN enabled=1 THEN 0 ELSE 1 END WHERE id=? AND organization_id=?'; $db->prepare($sql)->execute([$id,$organizationId]); if($action==='toggle'){(new RouterOSProvisioningService($db,(int)$organizationId))->setEnabled('network_static_ip',$id,!$currentEnabled);} $message=$action==='delete'?'Static IP dihapus.':'Status static IP diubah.'; }
 if($action==='save'){ $routerId=(int)($_POST['router_id']??0); $customerId=(int)($_POST['customer_id']??0); $subscriptionId=(int)($_POST['subscription_id']??0); $ip=trim((string)($_POST['ip_address']??'')); $gateway=trim((string)($_POST['gateway']??'')); $interface=trim((string)($_POST['interface_name']??'')); $status=strtoupper((string)($_POST['status']??'ACTIVE')); $comment=trim((string)($_POST['comment']??'')); if(!$routerId||!filter_var($ip,FILTER_VALIDATE_IP)||!in_array($status,['ACTIVE','SUSPENDED','RESERVED','RELEASED'],true)) throw new RuntimeException('Router, IP, dan status wajib valid.'); $check=$db->prepare('SELECT id FROM mikrotik_routers WHERE id=? AND organization_id=?'); $check->execute([$routerId,$organizationId]); if(!$check->fetchColumn()) throw new RuntimeException('Router bukan milik organisasi.'); foreach([['customers',$customerId],['subscriptions',$subscriptionId]] as [$table,$value]){if($value){$check=$db->prepare("SELECT id FROM {$table} WHERE id=? AND organization_id=?");$check->execute([$value,$organizationId]);if(!$check->fetchColumn())throw new RuntimeException('Relasi tenant tidak valid.');}} $values=[$routerId,$customerId?:null,$subscriptionId?:null,$ip,$gateway?:null,$interface?:null,$status,$comment?:null]; if($id){$db->prepare('UPDATE network_static_ips SET router_id=?,customer_id=?,subscription_id=?,ip_address=?,gateway=?,interface_name=?,status=?,comment=? WHERE id=? AND organization_id=?')->execute([...$values,$id,$organizationId]);}else{$db->prepare('INSERT INTO network_static_ips (organization_id,router_id,customer_id,subscription_id,ip_address,gateway,interface_name,status,comment) VALUES (?,?,?,?,?,?,?,?,?)')->execute([$organizationId,...$values]);}$message='Static IP berhasil disimpan.'; }
 } catch(Throwable $e){$error=$e->getMessage();} }
 $editId=(int)($_GET['edit']??0); $edit=null; if($editId){$q=$db->prepare('SELECT * FROM network_static_ips WHERE id=? AND organization_id=?');$q->execute([$editId,$organizationId]);$edit=$q->fetch(PDO::FETCH_ASSOC)?:null;}
$q=$db->prepare('SELECT id,name,host FROM mikrotik_routers WHERE organization_id=? ORDER BY name');$q->execute([$organizationId]);$routers=$q->fetchAll(PDO::FETCH_ASSOC);$q=$db->prepare('SELECT id,customer_code,name FROM customers WHERE organization_id=? ORDER BY name');$q->execute([$organizationId]);$customers=$q->fetchAll(PDO::FETCH_ASSOC);$q=$db->prepare('SELECT id,service_name,username FROM subscriptions WHERE organization_id=? ORDER BY service_name');$q->execute([$organizationId]);$subscriptions=$q->fetchAll(PDO::FETCH_ASSOC);$q=$db->prepare('SELECT s.*,r.name router_name,c.name customer_name FROM network_static_ips s JOIN mikrotik_routers r ON r.id=s.router_id AND r.organization_id=s.organization_id LEFT JOIN customers c ON c.id=s.customer_id AND c.organization_id=s.organization_id WHERE s.organization_id=? ORDER BY s.ip_address');$q->execute([$organizationId]);$items=$q->fetchAll(PDO::FETCH_ASSOC);
function sip_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} $pageTitle='Static IP Customers'; ob_start();
?>
<div class="container-fluid py-4"><h1>Static IP Customers</h1><p class="text-muted">IP static wajib terikat ke router MikroTik tenant.</p><?php if($message):?><div class="alert alert-success"><?=sip_h($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=sip_h($error)?></div><?php endif;?><div class="card mb-4"><div class="card-body"><h2 class="h5"><?= $edit?'Edit':'Tambah' ?> Static IP</h2><form method="post" class="row g-3"><input type="hidden" name="_csrf" value="<?=sip_h(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="col-md-3"><label class="form-label">Router</label><select class="form-select" name="router_id" required><option value="">Pilih router</option><?php foreach($routers as $v):?><option value="<?=$v['id']?>" <?=((int)($edit['router_id']??0)==$v['id']?'selected':'')?>><?=sip_h($v['name'].' - '.$v['host'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Customer</label><select class="form-select" name="customer_id"><option value="0">Tanpa customer</option><?php foreach($customers as $v):?><option value="<?=$v['id']?>" <?=((int)($edit['customer_id']??0)==$v['id']?'selected':'')?>><?=sip_h($v['customer_code'].' - '.$v['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Subscription</label><select class="form-select" name="subscription_id"><option value="0">Tanpa subscription</option><?php foreach($subscriptions as $v):?><option value="<?=$v['id']?>" <?=((int)($edit['subscription_id']??0)==$v['id']?'selected':'')?>><?=sip_h($v['service_name'].' '.$v['username'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">IP Address</label><input class="form-control" name="ip_address" value="<?=sip_h($edit['ip_address']??'')?>" required></div><div class="col-md-3"><label class="form-label">Gateway</label><input class="form-control" name="gateway" value="<?=sip_h($edit['gateway']??'')?>"></div><div class="col-md-3"><label class="form-label">Interface</label><input class="form-control" name="interface_name" value="<?=sip_h($edit['interface_name']??'')?>"></div><div class="col-md-3"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['ACTIVE','SUSPENDED','RESERVED','RELEASED'] as $v):?><option <?=$v===($edit['status']??'ACTIVE')?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Catatan</label><input class="form-control" name="comment" value="<?=sip_h($edit['comment']??'')?>"></div><div class="col-12"><button class="btn btn-primary">Simpan</button></div></form></div></div><div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>IP</th><th>Router</th><th>Customer</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><code><?=sip_h($i['ip_address'])?></code></td><td><?=sip_h($i['router_name'])?></td><td><?=sip_h($i['customer_name']??'-')?></td><td><?=$i['enabled']?'ENABLED':'DISABLED'?> / <?=sip_h($i['status'])?></td><td><a class="btn btn-sm btn-outline-primary" href="network_static_ip.php?edit=<?=$i['id']?>">Edit</a><form class="d-inline" method="post"><input type="hidden" name="_csrf" value="<?=sip_h(csrf_token())?>"><input type="hidden" name="id" value="<?=$i['id']?>"><button name="action" value="toggle" class="btn btn-sm btn-outline-warning">Enable/Disable</button><button name="action" value="delete" class="btn btn-sm btn-outline-danger">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div><?php $content=ob_get_clean();require __DIR__.'/../app/layout/layout.php';
